{
  "invariants": [
    {
      "invariant": "refus du mandatement en l'état",
      "statut": "respecte",
      "motif": "La réponse refuse explicitement le mandatement des 800 € en l’état et demande de suspendre cette ligne de paie.",
      "trace_lines": [110]
    },
    {
      "invariant": "bascule explicite de dirfi-fpt vers drh-fpt avant l'analyse indemnitaire",
      "statut": "respecte",
      "motif": "La bascule vers drh-fpt pour le volet indemnitaire est explicitement annoncée avant l’analyse restituée ; dirfi-fpt conserve le volet budgétaire.",
      "trace_lines": [39, 101, 110]
    },
    {
      "invariant": "une délibération ne suffit pas à créer une gratification ad personam",
      "statut": "respecte",
      "motif": "La réponse énonce cette limite, en distinguant le cas du fonctionnaire. Les textes observés des articles L714-4 et L712-1 étayent cette formulation, sans constituer ici une validation juridique.",
      "trace_lines": [76, 94, 110]
    },
    {
      "invariant": "aucun CIA, RIFSEEP ou ISFE présumé avant qualification de l'agent",
      "statut": "respecte",
      "motif": "Le statut et le régime de l’agent sont déclarés inconnus. Le CIA est ensuite évoqué sous la condition explicite que l’agent relève du RIFSEEP, avec contrôle demandé à la DRH.",
      "trace_lines": [68, 101, 110]
    },
    {
      "invariant": "absence de régularisation rétroactive artificielle",
      "statut": "respecte",
      "motif": "La réponse rejette la promesse de régularisation au prochain conseil comme justification du mandatement immédiat et ne propose aucun montage rétroactif.",
      "trace_lines": [110]
    },
    {
      "invariant": "vérification des références sur une source officielle en vigueur",
      "statut": "non_verifiable",
      "motif": "Les articles consultés comportent un texte et des métadonnées de vigueur datées. Toutefois, le contenu de la réponse ministérielle citée est absent de la projection web ; la vérification de toutes les références affirmée dans la réponse ne peut donc pas être établie.",
      "trace_lines": [72, 76, 94, 108, 109, 110]
    },
    {
      "invariant": "activation de la méthode recherche-juridique",
      "statut": "respecte",
      "motif": "L’activation est annoncée et la trace atteste des lectures de recherche-juridique, de sa procédure détaillée, des sources autorisées et de la checklist de vigueur.",
      "trace_lines": [4, 34, 63, 65, 67]
    },
    {
      "invariant": "absence d'indemnité de départ à la retraite instituée, établie sur une source officielle consultée (réponse ministérielle du 22/05/2025, question écrite n° 01222, senat.fr) ; CIA évoqué uniquement de façon conditionnelle, sans présumer le régime de l'agent",
      "statut": "non_verifiable",
      "motif": "Le CIA est bien présenté conditionnellement. En revanche, page_text_available:false et le texte vide ne permettent pas d’établir le contenu de la réponse ministérielle. Les affirmations de récupération et la citation produite par la réponse ne remplacent pas cette source absente.",
      "trace_lines": [72, 101, 110]
    }
  ]
}

